// Limpia las dos hojas del Excel y deja preparado qué hay que cargar y qué va al informe.
const MINIMO_ABONO_INICIAL = 5;
const FORMAS_PAGO = ['efectivo', 'tarjeta', 'bizum'];

const sinAcentos = s => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '');
const clave = s => sinAcentos(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

// 02/09/2026 y 7/9/26 → 2026-09-07
function fecha(s) {
  const m = String(s ?? '').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{2}|\d{4})$/);
  if (!m) return null;
  const año = m[3].length === 2 ? '20' + m[3] : m[3];
  return `${año}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
}

// 15€, 89.90, "1.842,30" → número
function importe(s) {
  let t = String(s ?? '').replace(/[€\s]/g, '').replace(/eur$/i, '');
  if (t.includes(',')) t = t.replace(/\./g, '').replace(',', '.');
  const n = Number(t);
  return t !== '' && Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
}

// carmen ruiz → Carmen Ruiz (las partículas se quedan en minúscula)
function nombre(s) {
  return String(s ?? '').trim().replace(/\s+/g, ' ').toLowerCase().split(' ')
    .map((p, i) => i > 0 && ['de', 'del', 'la', 'y'].includes(p) ? p : p.charAt(0).toUpperCase() + p.slice(1))
    .join(' ');
}

// 612345002 → 612 345 002; vacío → null
function telefono(s) {
  const d = String(s ?? '').replace(/\D/g, '');
  if (!d) return null;
  return d.length === 9 ? `${d.slice(0, 3)} ${d.slice(3, 6)} ${d.slice(6)}` : d;
}

const euros = n => `${n.toFixed(2).replace('.', ',')} €`;

function preparar(filasApartados, filasVentas) {
  const informe = { no_cargados: [], suposiciones: [], ignoradas: [], avisos: [] };

  // 1. Agrupar las filas de apartados por cliente + teléfono + modelo + talla.
  const grupos = new Map();
  filasApartados.forEach((f, i) => {
    const fila = i + 2; // fila 1 = cabecera
    const datos = {
      fila, fecha: fecha(f.fecha), cliente: nombre(f.cliente), telefono: telefono(f.telefono),
      producto: String(f.modelo ?? '').trim(), talla: String(f.talla ?? '').trim() || null,
      precio: importe(f.precio), importe: importe(f.abono), resta: importe(f.resta), notas: String(f.notas ?? '').trim(),
    };
    if (!datos.fecha || !datos.cliente || !datos.producto || datos.precio === null || datos.importe === null) {
      informe.no_cargados.push({ origen: 'apartados', fila, detalle: JSON.stringify(f), motivo: 'Fila incompleta o con datos ilegibles' });
      return;
    }
    const k = [clave(datos.cliente), (datos.telefono ?? '').replace(/\D/g, ''), clave(datos.producto), datos.talla].join('|');
    if (!grupos.has(k)) grupos.set(k, []);
    grupos.get(k).push(datos);
  });

  // 2. Primera fila = apartado con su abono inicial; las siguientes, abonos en orden de fecha.
  const apartados = [];
  for (const filas of grupos.values()) {
    filas.sort((a, b) => a.fecha.localeCompare(b.fecha) || a.fila - b.fila);
    const [primera, ...resto] = filas;
    const descripcion = `${primera.cliente} · ${primera.producto} T${primera.talla ?? '?'} (filas ${filas.map(f => f.fila).join(', ')})`;
    if (primera.importe < MINIMO_ABONO_INICIAL) {
      informe.no_cargados.push({
        origen: 'apartados', fila: filas.map(f => f.fila).join(', '), detalle: descripcion,
        motivo: `Abono inicial de ${euros(primera.importe)}, menor que el mínimo de ${euros(MINIMO_ABONO_INICIAL)}. No se carga el apartado ni sus ${resto.length} abono(s) posteriores (${euros(resto.reduce((s, f) => s + f.importe, 0))}).`
          + (filas.some(f => f.notas) ? ` Notas: ${filas.filter(f => f.notas).map(f => f.notas).join(' / ')}` : ''),
      });
      continue;
    }
    apartados.push({
      cliente: primera.cliente, telefono: primera.telefono, producto: primera.producto, talla: primera.talla,
      precio: primera.precio, fecha: primera.fecha, descripcion,
      pagos: filas.map(f => ({ fila: f.fila, fecha: f.fecha, importe: f.importe, forma_pago: null })),
      resta_excel: filas[filas.length - 1].resta,
    });
  }

  // 3. Ventas: fuera la fila de total; las que son abonos de un apartado no se cargan como venta.
  const ventas = [];
  filasVentas.forEach((f, i) => {
    const fila = i + 2;
    const concepto = String(f.concepto ?? '').trim();
    // En el Excel el texto del total está en la columna de la fecha.
    if ([f.fecha, concepto].some(c => /^total\b/.test(clave(c)))) {
      informe.ignoradas.push({ fila, detalle: `${String(f.fecha || concepto).trim()}: ${f.importe}`, motivo: 'Total sumado a mano: no es una venta' });
      return;
    }
    const v = { fila, fecha: fecha(f.fecha), concepto, importe: importe(f.importe), forma_pago: clave(f.forma_pago) };
    if (!v.fecha || !v.concepto || v.importe === null || !FORMAS_PAGO.includes(v.forma_pago)) {
      informe.no_cargados.push({ origen: 'ventas', fila, detalle: JSON.stringify(f), motivo: 'Fila incompleta, importe ilegible o forma de pago no válida' });
      return;
    }
    if (!/\b(abono|apartado)\b/.test(clave(concepto))) {
      ventas.push(v);
      return;
    }
    // Es un abono: buscar el pago del apartado con la misma fecha, el mismo importe y el cliente o el modelo en el concepto.
    const palabras = new Set(clave(concepto).split(' '));
    const encaja = (a, p) => p.forma_pago === null && p.fecha === v.fecha && p.importe === v.importe
      && clave(`${a.cliente} ${a.producto}`).split(' ').some(w => w.length >= 4 && palabras.has(w));
    let encontrado = null;
    for (const a of apartados) {
      const p = a.pagos.find(p => encaja(a, p));
      if (p) { p.forma_pago = v.forma_pago; encontrado = a; break; }
    }
    if (encontrado) {
      informe.ignoradas.push({ fila, detalle: `${concepto}: ${euros(v.importe)}`, motivo: `Es un abono de ${encontrado.cliente}; no se carga como venta y da su forma de pago (${v.forma_pago})` });
    } else {
      informe.no_cargados.push({ origen: 'ventas', fila, detalle: `${concepto}: ${euros(v.importe)}`, motivo: 'Parece el abono de un apartado pero no coincide con ninguno cargado; no se carga como venta para no contarlo dos veces' });
    }
  });

  // 4. Pagos sin forma de pago conocida: se supone efectivo y se informa.
  for (const a of apartados) {
    for (const p of a.pagos) {
      if (p.forma_pago === null) {
        p.forma_pago = 'efectivo';
        informe.suposiciones.push({ fila: p.fila, detalle: `${a.cliente} · ${p.fecha} · ${euros(p.importe)}`, motivo: 'Forma de pago desconocida: se carga como efectivo' });
      }
    }
  }

  const fechas = [...apartados.flatMap(a => a.pagos.map(p => p.fecha)), ...ventas.map(v => v.fecha)].sort();
  return { apartados, ventas, informe, desde: fechas[0] ?? null, hasta: fechas[fechas.length - 1] ?? null };
}

const r = preparar($('Extraer apartados').all().map(i => i.json), $('Extraer ventas').all().map(i => i.json));
return [{ json: r }];

const clave = s => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const filas = nodo => $(nodo).all().map(i => i.json).filter(x => x.id !== undefined);
// Un apartado del Excel ya está en la app si coinciden cliente, producto y fecha.
const claveApartado = a => [clave(a.cliente), clave(a.producto), a.fecha].join('|');

const plan = $('Preparar migración').first().json;
const enApp = new Map(filas('Apartados en la app').map(a => [claveApartado(a), a.id]));
const abonosApp = filas('Abonos en la app');
const ventasApp = filas('Ventas en la app');

// De un apartado nuevo faltan los pagos posteriores al inicial; de uno que ya estaba,
// los pagos que no tienen ya un abono con la misma fecha e importe.
const apartados = plan.apartados.map(a => {
  const id = enApp.get(claveApartado(a)) ?? null;
  const pagosQueFaltan = id === null ? a.pagos.slice(1) : a.pagos.filter(p => {
    const i = abonosApp.findIndex(x => x.apartado_id === id && x.fecha === p.fecha && x.importe === p.importe);
    if (i === -1) return true;
    abonosApp.splice(i, 1);
    return false;
  });
  return { clave: claveApartado(a), id, cliente: a.cliente, descripcion: a.descripcion, resta_excel: a.resta_excel, pagosQueFaltan,
    body: { cliente: a.cliente, telefono: a.telefono, producto: a.producto, talla: a.talla, precio: a.precio,
            abono_inicial: a.pagos[0].importe, forma_pago: a.pagos[0].forma_pago, fecha: a.fecha } };
});

// Una venta ya existe si coinciden fecha, concepto e importe.
const ventasNuevas = plan.ventas.filter(v => {
  const i = ventasApp.findIndex(x => x.fecha === v.fecha && clave(x.concepto) === clave(v.concepto) && x.importe === v.importe);
  if (i === -1) return true;
  ventasApp.splice(i, 1);
  return false;
}).map(v => ({ descripcion: `${v.fecha} · ${v.concepto} · ${v.importe} €`,
  body: { concepto: v.concepto, importe: v.importe, forma_pago: v.forma_pago, fecha: v.fecha } }));

return [{ json: { apartados, ventasNuevas } }];

// Los apartados que "Cuadrar con la app" no ha encontrado en la app.
const { apartados } = $('Cuadrar con la app').first().json;
const nuevos = apartados.filter(a => a.id === null);
if (nuevos.length === 0) return [{ json: { vacio: true } }];
return nuevos.map(a => ({ json: { clave: a.clave, descripcion: a.descripcion, body: a.body } }));

// Ids de todos los apartados del Excel en la app: los que ya estaban y los que se acaban de crear.
const { apartados } = $('Cuadrar con la app').first().json;
const ids = Object.fromEntries(apartados.filter(a => a.id !== null).map(a => [a.clave, a.id]));
if ($('Crear apartado').isExecuted) {
  const pedidos = $('Apartados a crear').all();
  $('Crear apartado').all().forEach((it, i) => {
    const r = it.json;
    if (r.statusCode === 201) ids[pedidos[i].json.clave] = r.body.id;
    else if (r.statusCode !== 422) throw new Error(`La tienda respondió ${r.statusCode} al crear un apartado: ${JSON.stringify(r.body)}`);
  });
}
return [{ json: { ids } }];

// Los pagos que faltan (de "Cuadrar con la app") en el apartado que les toca (de "Ids de los apartados").
const { apartados } = $('Cuadrar con la app').first().json;
const { ids } = $('Ids de los apartados').first().json;
const salida = [];
for (const a of apartados) {
  const id = ids[a.clave];
  if (id === undefined) continue; // la app rechazó el apartado: va al informe
  for (const p of a.pagosQueFaltan) {
    salida.push({ apartado_id: id, descripcion: `${a.cliente} · ${p.fecha} · ${p.importe} €`,
                  body: { importe: p.importe, forma_pago: p.forma_pago, fecha: p.fecha } });
  }
}
salida.sort((x, y) => x.body.fecha.localeCompare(y.body.fecha));
return salida.length ? salida.map(json => ({ json })) : [{ json: { vacio: true } }];

// Las ventas que "Cuadrar con la app" no ha encontrado en la app.
const { ventasNuevas } = $('Cuadrar con la app').first().json;
return ventasNuevas.length ? ventasNuevas.map(json => ({ json })) : [{ json: { vacio: true } }];

const filas = nodo => $(nodo).all().map(i => i.json).filter(x => x.id !== undefined);

const plan = $('Preparar migración').first().json;
const { apartados } = $('Cuadrar con la app').first().json;
const { ids } = $('Ids de los apartados').first().json;
const euros = n => `${Number(n).toFixed(2).replace('.', ',')} €`;
const detalle = d => typeof d === 'string' ? d : JSON.stringify(d);

// Resultado de cada petición de carga: 201 cargado, 422 rechazado por la app; otro código es un error.
function resultados(nodoPeticion, nodoPedidos) {
  if (!$(nodoPeticion).isExecuted) return { cargados: 0, rechazados: [] };
  const pedidos = $(nodoPedidos).all();
  const r = { cargados: 0, rechazados: [] };
  $(nodoPeticion).all().forEach((it, i) => {
    const { statusCode, body } = it.json;
    if (statusCode === 201) r.cargados++;
    else if (statusCode === 422) r.rechazados.push({ detalle: pedidos[i].json.descripcion, motivo: detalle(body?.detail) });
    else throw new Error(`La tienda respondió ${statusCode}: ${JSON.stringify(body)}`);
  });
  return r;
}
const ap = resultados('Crear apartado', 'Apartados a crear');
const ab = resultados('Registrar abono', 'Abonos a cargar');
const ve = resultados('Registrar venta', 'Ventas a cargar');

// Comprobar que lo pendiente en la app coincide con la columna "resta" del Excel (cada apartado, por su id).
const finales = new Map(filas('Apartados al final').map(a => [a.id, a]));
const descuadres = [];
for (const a of apartados) {
  const f = ids[a.clave] === undefined ? undefined : finales.get(ids[a.clave]);
  if (!f) descuadres.push(`${a.descripcion}: no está en la app`);
  else if (Math.abs(f.pendiente - a.resta_excel) > 0.005)
    descuadres.push(`${a.descripcion}: en la app faltan ${euros(f.pendiente)}, en el Excel ${euros(a.resta_excel)}`);
}

// Totales del Excel (lo cargable) frente a lo que hay en la app en esas fechas.
const suma = xs => Math.round(xs.reduce((s, x) => s + x, 0) * 100) / 100;
const totales = {
  abonos_excel: suma(plan.apartados.flatMap(a => a.pagos.map(p => p.importe))),
  abonos_app: suma(filas('Abonos al final').map(a => a.importe)),
  ventas_excel: suma(plan.ventas.map(v => v.importe)),
  ventas_app: suma(filas('Ventas al final').map(v => v.importe)),
};
if (totales.abonos_excel !== totales.abonos_app || totales.ventas_excel !== totales.ventas_app)
  descuadres.push('Los totales no coinciden: puede que la app no estuviera vacía o que la app haya rechazado algo (ver arriba).');

const lista = (titulo, xs, f) => xs.length ? [`${titulo} (${xs.length})`, ...xs.map(x => '- ' + f(x)), ''] : [];
const rechazados = [...ap.rechazados, ...ab.rechazados, ...ve.rechazados];
const texto = [
  'Hola, Marisa:',
  '',
  'Ha terminado la migración del Excel a la app. Resumen:',
  '',
  `- Apartados cargados ahora: ${ap.cargados} de ${plan.apartados.length} (los demás ya estaban o los rechazó la app)`,
  `- Abonos posteriores cargados ahora: ${ab.cargados}`,
  `- Ventas cargadas ahora: ${ve.cargados} de ${plan.ventas.length}`,
  `- Abonos: ${euros(totales.abonos_excel)} en el Excel y ${euros(totales.abonos_app)} en la app`,
  `- Ventas: ${euros(totales.ventas_excel)} en el Excel y ${euros(totales.ventas_app)} en la app`,
  '',
  ...lista('NO SE HA CARGADO, revísalo tú', plan.informe.no_cargados, x => `fila ${x.fila} de ${x.origen}: ${x.detalle}. ${x.motivo}`),
  ...lista('LA APP LO HA RECHAZADO', rechazados, x => `${x.detalle}: ${x.motivo}`),
  ...lista('DESCUADRES', descuadres, x => x),
  ...lista('SUPOSICIONES (confírmalas)', plan.informe.suposiciones, x => `fila ${x.fila}: ${x.detalle}. ${x.motivo}`),
  ...lista('Filas que no se han cargado a propósito', plan.informe.ignoradas, x => `fila ${x.fila} de ventas: ${x.detalle}. ${x.motivo}`),
  'Este correo lo envía el flujo "Migración Excel" de n8n.',
].join('\n');

// Los cinco primeros campos se llaman como las entradas de "SUB - Enviar notificación".
return [{ json: {
  destinatario: 'tienda', email: '',
  asunto: rechazados.length || descuadres.length || plan.informe.no_cargados.length
    ? 'Migración del Excel: terminada, con casos para revisar' : 'Migración del Excel: terminada sin incidencias',
  mensaje: texto, contexto: 'Migración del Excel', totales,
  cargados: { apartados: ap.cargados, abonos: ab.cargados, ventas: ve.cargados },
  rechazados, descuadres,
} }];
